346|  // 3D object follows the mouse, teal light follows the cursor
347|  const card=document.getElementById('card'), obj=document.getElementById('obj');
348|  card.addEventListener('mousemove',e=>{
349|    const r=card.getBoundingClientRect(), x=(e.clientX-r.left)/r.width, y=(e.clientY-r.top)/r.height;
350|    obj.style.transform=`rotateY(${(x-.5)*16}deg) rotateX(${(.5-y)*10}deg) translateZ(20px)`;
351|    card.style.setProperty('--mx',x*100+'%'); card.style.setProperty('--my',y*100+'%');
352|  });
353|  card.addEventListener('mouseleave',()=>obj.style.transform='');
354|
355|  // "Runs privately" toggle
356|  const tg=document.getElementById('toggle');
357|  tg.onclick=()=>{tg.classList.toggle('off');const s=tg.querySelectorAll('span');s[0].classList.toggle('act');s[1].classList.toggle('act');};
358|
359|  // scroll reveal + count-up + factory light
360|  const io=new IntersectionObserver(es=>es.forEach(e=>{
361|    if(!e.isIntersecting)return; e.target.classList.add('in'); io.unobserve(e.target);
362|    e.target.querySelectorAll('.count').forEach(c=>{
363|      const to=+c.dataset.to, dec=+(c.dataset.dec||0), t0=performance.now();
364|      const f=t=>{const p=Math.min((t-t0)/1400,1), v=to*(1-Math.pow(1-p,3)); c.textContent=v.toFixed(dec); if(p<1)requestAnimationFrame(f)};
365|      requestAnimationFrame(f);
366|    });
367|    if(e.target.id==='factory'){
368|      const nodes=[...document.querySelectorAll('#flow .node')]; let i=0;
369|      setInterval(()=>{nodes.forEach(n=>n.classList.remove('lit')); nodes[i%nodes.length].classList.add('lit'); i++;},900);
370|    }
371|  }),{threshold:.2});
372|  document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
373|
374|  // recorded demo run
375|  const steps=[...document.querySelectorAll('#steps li')], timer=document.getElementById('timer');
376|  const seq=[['write',1100],['build',1100],['measure',1100],['fix',1300],['write',800],['build',800],['measure',800],['done',600]];
377|  document.getElementById('run').onclick=()=>{
378|    steps.forEach(s=>s.className='');
379|    ['result','ask'].forEach(id=>document.getElementById(id).classList.remove('show'));
380|    let t=0,round=0;const start=Date.now();
381|    const tick=setInterval(()=>timer.textContent='recorded run · '+((Date.now()-start)/1000).toFixed(0)+' s',200);
382|    seq.forEach(([k,d])=>{t+=d;setTimeout(()=>{
383|      const li=steps.find(s=>s.dataset.k===k);
384|      steps.forEach(s=>{if(s.classList.contains('on'))s.classList.replace('on','done')});
385|      if(k==='fix'){round++;li.className='fix';document.getElementById('fixnote').textContent='measured 2 solids, expected 1 → fixing (round '+round+' of 3)';steps.slice(0,3).forEach(s=>s.className='');}
386|      else li.className='on';
387|      if(k==='done'){li.className='done';clearInterval(tick);timer.textContent='PASS ✓ · recorded run';
388|        ['result','ask'].forEach(id=>document.getElementById(id).classList.add('show'));}
389|    },t)});
390|  };
391|  document.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>document.getElementById('job').value=b.textContent+'…');
392|</script>
